bool adjustment(Layer& layer,const PhotoshopExtras& extra){
    if(extra.contains("levl")){Reader r{extra["levl"]};if(r.bytes.size()<292)return false;r.u16();effects_tools::LevelsSettings settings;for(size_t c=0;c<4;++c){auto& s=settings.ranges[c];s.black=r.u16();s.white=r.u16();s.outputBlack=r.u16();s.outputWhite=r.u16();s.gamma=r.u16()/256.;}layer.adjustmentJson=effects_tools::withLevelsSettings(effects::defaultAdjustmentJson("Levels"),settings);return true;}
    if(extra.contains("curv")){Reader r{extra["curv"]};if(r.bytes.size()<5)return false;if(r.bytes[0]==0)r.u8();const auto version=r.u16();if(version!=1&&version!=4)return false;auto count=r.u16();effects_tools::CurvesSettings settings;for(unsigned c=0;c<std::min<unsigned>(4,count);++c){const auto n=r.u16();if(n>32)return false;std::vector<Point> curve;for(unsigned p=0;p<n;++p){auto y=r.u16(),x=r.u16();curve.push_back({double(std::min<unsigned>(255,x)),double(std::min<unsigned>(255,y))});}if(curve.size()<2)continue;std::sort(curve.begin(),curve.end(),[](auto a,auto b){return a.x<b.x;});if(curve.front().x>0)curve.insert(curve.begin(),{0,curve.front().y});if(curve.back().x<255)curve.push_back({255,curve.back().y});settings.channels[c]=std::move(curve);}layer.adjustmentJson=effects_tools::withCurvesSettings(effects::defaultAdjustmentJson("Curves"),settings);return true;}
    if(extra.contains("hue2")||extra.contains("hue ")){Reader r{extra.value("hue2",extra.value("hue "))};r.u16();effects_tools::HueSettings settings;settings.colorize=r.u8()!=0;r.u8();for(size_t c=0;c<7&&r.at+6<=r.bytes.size();++c){auto& s=settings.adjustments[c];s.hue=int16_t(r.u16());s.saturation=int16_t(r.u16());s.lightness=int16_t(r.u16());}layer.adjustmentJson=effects_tools::withHueSettings(effects::defaultAdjustmentJson("Hue/Saturation"),settings);return true;}return false;
}
