void applyPhotoshopMetadata(Layer& layer,const PhotoshopExtras& extra,int canvasWidth,int canvasHeight,QStringList& conversions,const ImportOptions& options){
    QStringList notes;
    if(extra.contains("TySh")||extra.contains("tySh")||extra.contains("txt2")){try{Point anchor;double rotation=0;bool flipY=false,frame=false;const auto style=textStyle(extra.value("TySh",extra.value("tySh")),notes,anchor,rotation,flipY,frame);if(style){auto json=QJsonDocument(*style).toJson(QJsonDocument::Compact).toStdString();auto parsed=editing::decodeTextStyle(json);auto size=editing::textBoxSize(parsed);checkedBytes(uint32_t(std::ceil(size.width())),uint32_t(std::ceil(size.height())),4,options);auto raster=editing::textRaster(parsed);Point local{frame?12:parsed.alignment==editing::TextAlignment::Right?raster->width-12:parsed.alignment==editing::TextAlignment::Center?raster->width/2.:12,frame?12:editing::textFirstBaseline(parsed)};Transform placement{0,0,double(raster->width),double(raster->height),rotation,false,flipY};auto mapped=placement.fromUnit({local.x/raster->width,local.y/raster->height});placement.x=anchor.x-mapped.x;placement.y=anchor.y-mapped.y;layer.textJson=json;layer.raster=raster;layer.transform=placement;if(!QFontDatabase::families().contains(style->value("fontName").toString()))notes.append("The original font may require substitution when text is edited on Windows.");}else notes.append("Unsupported editable Photoshop text was kept as pixels.");}catch(const std::exception&){notes.append("Unsupported editable Photoshop text was kept as pixels.");}}
    else if(extra.contains("vmsk")||extra.contains("vsms")||extra.contains("vogk")){bool editable=false;try{editable=shape(layer,extra,canvasWidth,canvasHeight,notes,options);}catch(const std::exception&){if(!layer.raster)throw;}if(!editable)notes.append("Vector shape was imported as pixels.");}
    else if(extra.contains("SoLd")||extra.contains("SoLE"))notes.append("The smart object was rasterized; linked contents cannot be edited.");
    if(!layer.group){static const QList<QByteArray> keys{"levl","curv","hue2","hue ","expA","grdm","brit","blnc","nvrt","thrs","post","mixr","selc","blwh","phfl","vibA"};bool has=false;for(const auto& k:keys)has|=extra.contains(k);if(has){bool converted=false;try{converted=adjustment(layer,extra);}catch(const std::exception&){}if(converted){layer.raster.reset();layer.transform={0,0,double(canvasWidth),double(canvasHeight)};notes.append("Adjustment parameters may differ from Photoshop.");}else{conversions.append(QString::fromStdString(layer.name)+": Unsupported Photoshop adjustment was skipped.");layer.name.clear();return;}}}
    for(const auto& note:notes)conversions.append(QString::fromStdString(layer.name)+": "+note);
}
